<?php
 namespace QQWorld\Framework\View\Test\Unit\Design\Theme; use QQWorld\Framework\App\Filesystem\DirectoryList; class ImageTest extends \PHPUnit\Framework\TestCase { protected $_model; protected $_filesystemMock; protected $_imageMock; protected $_uploaderMock; protected $_themeMock; protected $_mediaDirectoryMock; protected $_rootDirectoryMock; protected $imagePathMock; protected function setUp() { $this->_mediaDirectoryMock = $this->createPartialMock(\QQWorld\Framework\Filesystem\Directory\Write::class, ['isExist', 'copyFile', 'getRelativePath', 'delete']); $this->_rootDirectoryMock = $this->createPartialMock(\QQWorld\Framework\Filesystem\Directory\Write::class, ['isExist', 'copyFile', 'getRelativePath', 'delete']); $this->_filesystemMock = $this->createPartialMock(\QQWorld\Framework\Filesystem::class, ['getDirectoryWrite', '__wakeup', 'delete']); $this->_filesystemMock->expects($this->at(0)) ->method('getDirectoryWrite') ->with(DirectoryList::MEDIA) ->will($this->returnValue($this->_mediaDirectoryMock)); $this->_filesystemMock->expects($this->at(1)) ->method('getDirectoryWrite') ->with(DirectoryList::ROOT) ->will($this->returnValue($this->_rootDirectoryMock)); $imageFactory = $this->createMock(\QQWorld\Framework\Image\Factory::class); $this->_imageMock = $this->createMock(\QQWorld\Framework\Image::class); $imageFactory->expects($this->any())->method('create')->will($this->returnValue($this->_imageMock)); $logger = $this->createMock(\Psr\Log\LoggerInterface::class); $this->_themeMock = $this->createPartialMock(\QQWorld\Theme\Model\Theme::class, ['__wakeup']); $this->_uploaderMock = $this->createMock(\QQWorld\Framework\View\Design\Theme\Image\Uploader::class); $this->imagePathMock = $this->_getImagePathMock(); $objectManager = new \QQWorld\Framework\TestFramework\Unit\Helper\ObjectManager($this); $this->_model = $objectManager->getObject( \QQWorld\Framework\View\Design\Theme\Image::class, [ 'filesystem' => $this->_filesystemMock, 'imageFactory' => $imageFactory, 'uploader' => $this->_uploaderMock, 'themeImagePath' => $this->imagePathMock, 'logger' => $logger, 'theme' => $this->_themeMock ]); } protected function tearDown() { $this->_model = null; $this->_filesystemMock = null; $this->_imageMock = null; $this->_uploaderMock = null; $this->_themeMock = null; } protected function _getImagePathMock() { $imagePathMock = $this->createMock(\QQWorld\Theme\Model\Theme\Image\Path::class); $testBaseUrl = 'http://localhost/media_path/'; $imagePathMock->expects($this->any())->method('getPreviewImageDefaultUrl') ->will($this->returnValue($testBaseUrl . 'test_default_preview.png')); $testBaseDir = '/media_path/'; $imagePathMock->expects( $this->any() )->method( 'getImagePreviewDirectory' )->will( $this->returnValue($testBaseDir . 'theme/preview') ); $imagePathMock->expects( $this->any() )->method( 'getTemporaryDirectory' )->will( $this->returnValue($testBaseDir . 'tmp') ); return $imagePathMock; } protected function _getThemeSampleData() { return [ 'theme_id' => 1, 'theme_title' => 'Sample theme', 'preview_image' => 'images/preview.png', 'area' => \QQWorld\Framework\App\Area::AREA_FRONTEND, 'type' => \QQWorld\Framework\View\Design\ThemeInterface::TYPE_VIRTUAL ]; } public function testConstructor() { $this->assertNotEmpty($this->_model); } public function testCreatePreviewImage() { $this->_themeMock->setData($this->_getThemeSampleData()); $this->_themeMock->setData('preview_image', null); $this->_imageMock->expects( $this->once() )->method( 'save' )->with( '/media_path/theme/preview', $this->anything() ); $this->_model->createPreviewImage('/some/path/to/image.png'); $this->assertNotNull($this->_themeMock->getData('preview_image')); } public function testCreatePreviewImageCopy() { $previewImage = 'test_preview.png'; $relativePath = '/media_path/theme/preview/test_preview.png'; $this->_themeMock->setData($this->_getThemeSampleData()); $this->_themeMock->setData('preview_image', $previewImage); $this->_mediaDirectoryMock->expects($this->once()) ->method('getRelativePath') ->will($this->returnArgument(0)); $this->_rootDirectoryMock->expects($this->once()) ->method('getRelativePath') ->with($previewImage) ->will($this->returnValue($relativePath)); $this->_rootDirectoryMock->expects($this->once()) ->method('copyFile') ->with($relativePath, $this->anything()) ->will($this->returnValue(true)); $themeImageMock = $this->getMockBuilder(\QQWorld\Framework\View\Design\Theme\Image::class) ->disableOriginalConstructor() ->setMethods(['getPreviewImagePath']) ->getMock(); $themeImageMock->expects($this->atLeastOnce()) ->method('getPreviewImagePath') ->will($this->returnValue($previewImage)); $themeMock = $this->getMockBuilder(\QQWorld\Theme\Model\Theme::class) ->disableOriginalConstructor() ->setMethods(['getThemeImage', 'getPreviewImage', '__wakeup']) ->getMock(); $themeMock->expects($this->atLeastOnce()) ->method('getPreviewImage') ->will($this->returnValue($previewImage)); $themeMock->expects($this->atLeastOnce()) ->method('getThemeImage') ->will($this->returnValue($themeImageMock)); $this->assertTrue($this->_model->createPreviewImageCopy($themeMock)); $this->assertEquals($previewImage, $this->_themeMock->getData('preview_image')); } public function testRemovePreviewImage() { $this->_themeMock->setData($this->_getThemeSampleData()); $this->_themeMock->setData('preview_image', 'test.png'); $this->_mediaDirectoryMock->expects($this->once())->method('delete'); $this->_model->removePreviewImage(); $this->assertNull($this->_themeMock->getData('preview_image')); } public function testRemoveEmptyPreviewImage() { $this->_themeMock->setData($this->_getThemeSampleData()); $this->_themeMock->setData('preview_image', null); $this->_filesystemMock->expects($this->never())->method('delete'); $this->_model->removePreviewImage(); $this->assertNull($this->_themeMock->getData('preview_image')); } public function testUploadPreviewImage() { $scope = 'test_scope'; $tmpFilePath = '/media_path/tmp/temporary.png'; $this->_themeMock->setData($this->_getThemeSampleData()); $this->_themeMock->setData('preview_image', 'test.png'); $this->_uploaderMock->expects( $this->once() )->method( 'uploadPreviewImage' )->with( $scope, '/media_path/tmp' )->will( $this->returnValue($tmpFilePath) ); $this->_mediaDirectoryMock->expects($this->at(0))->method('getRelativePath')->will($this->returnArgument(0)); $this->_mediaDirectoryMock->expects($this->at(1))->method('delete')->with($this->stringContains('test.png')); $this->_mediaDirectoryMock->expects($this->at(2))->method('delete')->with($tmpFilePath); $this->_model->uploadPreviewImage($scope); } public function testGetPreviewImageUrl() { $this->_themeMock->setData($this->_getThemeSampleData()); $this->imagePathMock->expects($this->any()) ->method('getPreviewImageUrl') ->with($this->_themeMock) ->will($this->returnValue('http://localhost/media_path/preview/image.png')); $this->assertEquals('http://localhost/media_path/preview/image.png', $this->_model->getPreviewImageUrl()); } public function testGetDefaultPreviewImageUrl() { $this->_themeMock->setData($this->_getThemeSampleData()); $this->_themeMock->setData('preview_image', null); $this->assertEquals( 'http://localhost/media_path/test_default_preview.png', $this->_model->getPreviewImageUrl() ); } } 